gae5(){return"\u0645\u0628\u0627\u0631\u0627\u0629 \u0648\u062f\u064a\u0629"},
gBL(){return"\u0623\u0645\u0633"},
gaee(){return"\u0636\u063a\u0637 \u0639\u0627\u0644\u064d"},
